<script setup>
import {ref,onMounted,watch} from 'vue';import PageHeader from '../../components/common/PageHeader.vue';import {getOrders} from '../../api/orders.js'
const status=ref(''),items=ref([]);async function load(){items.value=(await getOrders({status:status.value})).data.items}onMounted(load);watch(status,load)
</script>
<template><div class="page-shell"><div class="container"><PageHeader title="我的订单" description="查看定制方案从确认到生产安装的完整进度。" :breadcrumbs="['首页','我的定制','我的订单']"><el-button type="primary" @click="$router.push('/customize')">新建定制</el-button></PageHeader><div class="filter-bar"><el-select v-model="status" clearable placeholder="全部状态" style="width:150px"><el-option label="进行中" value="进行中"/><el-option label="已完成" value="已完成"/></el-select><el-input placeholder="订单号 / 项目名称" style="width:240px" clearable/><span class="muted">共 {{items.length}} 条</span></div><div class="table-section list-table"><el-table :data="items"><el-table-column prop="id" label="订单号" min-width="160"/><el-table-column prop="name" label="项目名称" min-width="220"/><el-table-column prop="createdAt" label="创建日期" width="130"/><el-table-column label="状态" width="120"><template #default="{row}"><span :class="['status-dot',row.status==='已完成'?'success':'progress']"></span>{{row.stage}}</template></el-table-column><el-table-column prop="delivery" label="预计交付" width="130"/><el-table-column label="操作" width="120" fixed="right"><template #default="{row}"><router-link :to="`/orders/${row.id}`" class="text-link">查看详情</router-link></template></el-table-column></el-table><div class="pagination"><el-pagination background layout="prev, pager, next" :total="items.length" :page-size="10"/></div></div></div></div></template>
<style scoped>.list-table{margin-top:24px}.pagination{display:flex;justify-content:flex-end;padding-top:18px}</style>
